import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import API from './api/axiosClient';
import Layout from './components/Layout';
import Login from './pages/Login';
import Register from './pages/Register';
import CustomerDashboard from './pages/CustomerDashboard';
import WorkerDashboard from './pages/WorkerDashboard';

const queryClient = new QueryClient();

export default function App() {
    const orgId = 'org_alpha'; 
    const machineId = 'MACH_01';

    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        API.get(`/auth/${orgId}/me`)
            .then(res => setUser(res.data))
            .catch(() => setUser(null))
            .finally(() => setLoading(false));
    }, [orgId]);

    if (loading) {
        return <div className="min-h-screen bg-gray-900 text-white flex items-center justify-center">Loading session...</div>;
    }

    return (
        <QueryClientProvider client={queryClient}>
            <Router>
                <Routes>
                    <Route element={<Layout user={user} setUser={setUser} />}>
                        {/* Public Auth Routes */}
                        <Route path="/login" element={<Login orgId={orgId} setUser={setUser} />} />
                        <Route path="/register" element={<Register orgId={orgId} />} />

                        {/* Customer Dashboard Route */}
                        <Route 
                            path="/customer" 
                            element={user?.role === 'customer' ? <CustomerDashboard orgId={orgId} /> : <Navigate to="/login" replace />} 
                        />

                        {/* Worker & Admin Terminal Dashboard Route */}
                        <Route 
                            path="/worker" 
                            element={[ 'admin'].includes(user?.role) ? <WorkerDashboard orgId={orgId} machineId={machineId} /> : <Navigate to="/login" replace />} 
                        />

                        {/* Automatic Root Redirect Based on Auth Status */}
                        <Route 
                            path="/" 
                            element={
                                user ? (
                                    <Navigate to={user.role === 'customer' ? '/customer' : '/worker'} replace />
                                ) : (
                                    <Navigate to="/login" replace />
                                )
                            } 
                        />
                        <Route path="*" element={<Navigate to="/" replace />} />
                    </Route>
                </Routes>
            </Router>
        </QueryClientProvider>
    );
}
